  for (const num of nums) {
    let value = num;
    for (let factor = 2; factor * factor <= value; factor++) {
      while (value % factor === 0) {
        primes.add(factor);
        value /= factor;
      }
    }
    if (value > 1) {
      primes.add(value);
    }
  }
