function distinctPrimeFactors(nums) {
  const isPrime = (p) => {
    for (let d = 2; d < p; d++) if (p % d === 0) return false;
    return p >= 2;
  };
  let count = 0;
  for (let p = 2; p <= 1000; p++) {
    if (isPrime(p) && nums.some(x => x % p === 0)) count++;
  }
  return count;
}

