function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.5 ? 2000 : int(500, 2000)) : int(1, 8);
  const mode = rand();
  const smooth = [2, 3, 5, 7, 11, 13].slice(0, int(1, 6));
  const value = () => {
    if (mode < 0.35) {
      // Products of a few small primes keep the answer small.
      for (;;) {
        let x = 1;
        const parts = int(1, 6);
        for (let k = 0; k < parts; k++) x *= smooth[int(0, smooth.length - 1)];
        if (x >= 2 && x <= 1000) return x;
      }
    }
    if (mode < 0.6) return int(2, large ? 60 : 30);
    return int(2, 1000);
  };
  return [Array.from({ length: n }, value)];
}
